+void test_bio_update_logging() {
+    // Setup
+    setup_test_environment();
+    clear_logs();
+    int test_user_id = 123;
+    const char* new_bio = "This is my new expert bio.";
+
+    // Action
+    update_user_bio(test_user_id, new_bio);
+
+    // Verification
